import { test } from 'node:test';
import assert from 'node:assert';
import { createState, step, frame, WIDTH, HEIGHT } from '../game/neon.js';

const mockCtx = {
  fillStyle: '',
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
};

test('Ball hitting brick from top should bounce', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - state.ball.r - 1;
  state.ball.vx = 0;
  state.ball.vy = 100;

  const dt = 0.02;
  step(state, dt);
  frame(mockCtx, state);

  assert.strictEqual(state.ball.vy < 0, true, `Ball should bounce UP (vy < 0), but is ${state.ball.vy}`);
});

test('Ball hitting two bricks on the same row should not cancel out (Double Inversion)', () => {
  const state = createState(1);
  // Ball moving right, hitting the seam between brick 0 and 1
  const b0 = state.bricks[0];
  const b1 = state.bricks[1];

  state.ball.y = b0.y + b0.h / 2;
  state.ball.x = b0.x + b0.w - state.ball.r + 1; // Inside b0, about to enter b1
  state.ball.vx = 100;
  state.ball.vy = 0;

  const dt = 0.01;
  step(state, dt);
  frame(mockCtx, state);

  assert.strictEqual(state.ball.vx < 0, true, `Ball should bounce LEFT (vx < 0), but is ${state.ball.vx}`);
});

# To Fix: Ball passes through bricks

**Symptôme joueur** : « la balle traverse les briques au lieu de rebondir »

## D1 — Absence de rebond (No Deflection)

- **Famille** : face vs coin
- **Symptôme joueur** : la balle traverse la brique sans changer de direction
- **Cause** : `game/neon.js:215` — Le bloc de collision marque la brique comme morte mais ne modifie ni `ball.vx` ni `ball.vy`.
- **Invariant violé** : Tout contact avec une brique doit entraîner une inversion de la vitesse sur l'axe de collision.
- **Déclencheur** : `state.ball` et `state.bricks[i]` satisfont `collides()`.
- **Attendu** : `ball.vy` doit devenir `< 0` lors d'un impact sur la face supérieure.
- **Référence** : https://noonat.github.io/intersect/ — AABB collision resolution.
- **Cas test** :
  ```js
  test('Ball hitting brick from top should bounce', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x + brick.w / 2;
    state.ball.y = brick.y - state.ball.r - 1;
    state.ball.vx = 0;
    state.ball.vy = 100;
    const dt = 0.02;
    step(state, dt);
    frame(mockCtx, state);
    assert.strictEqual(state.ball.vy < 0, true);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should bounce UP (vy < 0), but is 100`
- **Discrimine** : Une correction qui ignorerait l'axe d'impact (ex: inverser systématiquement `vy`).
- **Vert quand** : Le test de rebond haut/bas et gauche/droite passent.
- **Révélé par** : Symptôme initial.

## D2 — Recouvrement non résolu (Sticky/Phasing)

- **Famille** : Collant
- **Symptôme joueur** : la balle peut rester "coincée" dans une brique ou passer à travers si elle pénètre trop profondément.
- **Cause** : `game/neon.js:215` — Absence de repositionnement de la balle hors de la brique après le choc.
- **Invariant violé** : Après résolution, la balle ne doit plus chevaucher la brique.
- **Déclencheur** : Collision avec une pénétration $> 0$.
- **Attendu** : `ball.y` ou `ball.x` est corrigé pour être exactement au bord de la brique.
- **Référence** : https://gamedev.net/ — AABB collision response.
- **Cas test** :
  ```js
  test('Ball should be pushed out of brick after collision', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x + brick.w / 2;
    state.ball.y = brick.y + 1; // Deep penetration
    state.ball.vy = 100;
    frame(mockCtx, state);
    assert.strictEqual(state.ball.y + state.ball.r <= brick.y, true);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError: Ball should be pushed out...` (la position reste `brick.y + 1`)
- **Discrimine** : Une correction qui inverse la vitesse sans repositionner.
- **Vert quand** : La balle est repositionnée hors du rectangle.
- **Révélé par** : D1.

## D3 — Double inversion (Seam Ghost Collision)

- **Famille** : Double inversion
- **Symptôme joueur** : la balle traverse une rangée de briques en frappant la couture entre deux briques.
- **Cause** : `game/neon.js:212` — La boucle `for (const brick of state.bricks)` peut traiter deux collisions sur le même axe dans une seule frame, annulant le rebond.
- **Invariant violé** : Un rebond maximum par axe par passe de physique.
- **Déclencheur** : `ball.x` se trouve à cheval entre deux briques d'une même rangée avec `vx > 0`.
- **Attendu** : La vitesse `vx` est inversée une seule fois.
- **Référence** : Skill Playtest (Famille Double Inversion).
- **Cas test** :
  ```js
  test('Ball hitting two bricks on the same row should not cancel out', () => {
    const state = createState(1);
    const b0 = state.bricks[0];
    const b1 = state.bricks[1];
    state.ball.y = b0.y + b0.h / 2;
    state.ball.x = b0.x + b0.w - state.ball.r + 1;
    state.ball.vx = 100;
    state.ball.vy = 0;
    const dt = 0.01;
    step(state, dt);
    frame(mockCtx, state);
    assert.strictEqual(state.ball.vx < 0, true);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should bounce LEFT (vx < 0), but is 100`
- **Discrimine** : Une correction qui se contente d'itérer sur les briques et de faire `vx = -vx`.
- **Vert quand** : Le rebond est maintenu malgré le contact multiple.
- **Révélé par** : D1 et D2.

