  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - state.ball.r - 1;
  state.ball.vx = 0;
  state.ball.vy = 100;

  const dt = 0.02;
  step(state, dt);
  frame(mockCtx, state);

  assert.ok(state.ball.vy < 0, `Ball should bounce UP, but is ${state.ball.vy}`);
});

test('frame: ball should be pushed out of brick after collision', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + 1; // Deep penetration
  state.ball.vy = 100;
  frame(mockCtx, state);
  assert.ok(state.ball.y + state.ball.r <= brick.y || state.ball.y - state.ball.r >= brick.y + brick.h, 'Ball should not overlap brick after response');
});

test('frame: ball hitting two bricks on the same row should not cancel out (Double Inversion)', () => {
  const state = createState(1);
  const b0 = state.bricks[0];
  const b1 = state.bricks[1];
  state.ball.y = b0.y + b0.h / 2;
  state.ball.x = b0.x + b0.w - state.ball.r + 1;
  state.ball.vx = 100;
  state.ball.vy = 0;

  const dt = 0.01;
  step(state, dt);
  frame(mockCtx, state);

  assert.ok(state.ball.vx < 0, `Ball should bounce LEFT, but is ${state.ball.vx}`);
});

