const mockCtx = {
  fillStyle: '',
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
};

import {
  collides,
  step,
  makeBricks,
  createState,
  frame,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

// TODO (#5): test comboMultiplier / scoreForBrick.
// TODO      : test level progression and loadBest/saveBest persistence.

test('frame: ball hitting brick from top should bounce UP', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - state.ball.r - 1;
  state.ball.vx = 0;
  state.ball.vy = 100;

  const dt = 0.02;
  step(state, dt);
  frame(mockCtx, state);

  assert.ok(state.ball.vy < 0, `Ball should bounce UP, but is ${state.ball.vy}`);
});

test('frame: ball should be pushed out of brick after collision', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + 1; // Deep penetration
  state.ball.vy = 100;
  frame(mockCtx, state);
  assert.ok(state.ball.y + state.ball.r <= brick.y || state.ball.y - state.ball.r >= brick.y + brick.h, 'Ball should not overlap brick after response');
});

